// Authored I/O specifications for the original shared Challenge functions.
// These describe observable results, independently of the teaching example's
// implementation. A loop, library call, or equivalent formula may all be valid.
const example = (args, expected, explanation) => ({ args, expected, explanation });
const statement = (description, constraints, examples, ignoredInputs = []) => ({ description, constraints, examples, ignoredInputs });

