export function sharedChallengeStatement(topicId) {
 const value = SHARED_CHALLENGE_STATEMENTS[topicId];
 if (!value) throw new RangeError(`Missing Challenge statement: ${topicId}`);
 return {
  description: value.description,
  constraints: [...value.constraints, '入力・途中の計算・戻り値は、符号付き32ビット整数の範囲内です。'],
  examples: value.examples.map(value => ({ ...value, args: [...value.args] })),
  ignoredInputs: [...value.ignoredInputs]
 };
}
